  ('ict-board-rajshahi-2024-mcq-001', 'class9-ict-bn-guide', 'satt-ict-board.pdf p30', 'জনাব হাসানের জন্য কোন সফট্‌ওয়্যারটি বেশি উপযোগী?', 'mcq', '{"ক":"ওয়ার্ড প্রসেসিং","খ":"ডাটাবেজ","গ":"ভিডিও এডিটিং","ঘ":"প্রেজেন্টেশন"}'::jsonb, 'খ', 1, false, 'ict-board-rajshahi-2024-mcq', false, 'board-mcq', null, 'জনাব হাসান একটি বিদ্যালয়ের প্রধান শিক্ষক। তিনি তার বিদ্যালয় পরিচালনার কাজ সুষ্ঠু ভাবে সম্পন্ন করার জন্য কম্পিউটার ব্যবহার করতে চান।', 'rajshahi', 2024, true),
