  ('physics-board-barishal-2022-mcq-008', 'class9-physics-bn-guide', 'satt-physics-board.pdf p50', 'কর্মদক্ষতার ক্ষেত্রে- i. কর্মদক্ষতা =অপচয়কৃ ত শক্তি/মোট প্রদত্ত শক্তি ii. কর্মদক্ষতা =লভ্য কার্যকর শক্তি/মোট প্রদত্ত শক্তি iii. কর্মদক্ষতা = প্রদত্ত শক্তি—অপচয়কৃ ত শক্তি/প্রদত্ত শক্তি নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i","খ":"i ও ii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'গ', 1, false, 'physics-board-barishal-2022-mcq', false, 'board-mcq', null, null, 'barishal', 2022, true),
