  ('physics-board-barishal-2022-mcq-014', 'class9-physics-bn-guide', 'satt-physics-board.pdf p51', 'একটি স্লাইড ক্যালিপার্সের প্রধান স্কেলের ক্ষু দ্রতম 1 ঘরের দৈর্ঘ্য 1mm। ভার্নিয়ার স্কেলের ভাগ সংখ্যা 10। ভার্নিয়ার ধ্রুবকের মান কত?', 'mcq', '{"ক":"0.01 cm","খ":"0.001 mm","গ":"0.001 m","ঘ":"0.1 m"}'::jsonb, 'ক', 1, false, 'physics-board-barishal-2022-mcq', false, 'board-mcq', null, null, 'barishal', 2022, true),
